# ============================================================
# File   : scripts/yahoo_ca_bundle.py
# Version: V1-YAHOO-CA-BUNDLE
# ------------------------------------------------------------
# Purpose:
#   Windows 証明書ストアのルートCAを certifi のバンドルへ足した
#   CAバンドルを作り、CURL_CA_BUNDLE / SSL_CERT_FILE / REQUESTS_CA_BUNDLE
#   に設定する。
#
# Why:
#   この環境では Norton Antivirus の SSL/TLS スキャンが HTTPS を傍受し、
#   Norton が生成した中間CAで証明書が差し替えられる。
#     CN=Norton Web/Mail Shield Root
#     OU=generated by Norton Antivirus for SSL/TLS scanning
#   このルートCAは Windows の証明書ストアには入っているが certifi には
#   無いため、certifi しか見ない HTTP クライアントは Yahoo に到達できない。
#
#   2026-08-08 の実測:
#     curl_cffi (yfinance が使う)  certifi のみ -> NG / このバンドル -> HTTP 200
#     yfinance                     certifi のみ -> 0行 / このバンドル -> 321行
#     requests / urllib (OpenSSL)  どちらも NG
#       ("Basic Constraints of CA cert not marked critical" で
#        OpenSSL が証明書自体を拒否するため、バンドルでは解決できない)
#
#   したがって Yahoo 取得は yfinance (curl_cffi) 経路を使うこと。
#   urllib 直叩きの経路 (night_yahoo_daily_direct_chart_patch) は
#   この環境では通らない。
#
# Usage:
#   from scripts.yahoo_ca_bundle import install
#   install()
# ============================================================

from __future__ import annotations

import base64
import logging
import os
import ssl
from pathlib import Path
from typing import Optional

LOG = logging.getLogger("yahoo_ca_bundle")
VERSION = "V1-YAHOO-CA-BUNDLE"

_ENV_VARS = ("CURL_CA_BUNDLE", "SSL_CERT_FILE", "REQUESTS_CA_BUNDLE")
_INSTALLED = False


def _default_bundle_path() -> Path:
    override = os.environ.get("YAHOO_CA_BUNDLE_PATH", "").strip()
    if override:
        return Path(override)
    root = Path(__file__).resolve().parents[1]
    return root / "certs" / "ca_with_windows_store.pem"


def _windows_store_certs() -> list[bytes]:
    """Windows の証明書ストアから DER をすべて集める。"""
    out: list[bytes] = []
    enum_certificates = getattr(ssl, "enum_certificates", None)
    if enum_certificates is None:
        # Windows 以外では存在しない
        return out
    for store in ("ROOT", "CA"):
        try:
            for der, _enc, _trust in enum_certificates(store):
                out.append(der)
        except Exception:
            LOG.debug("[YAHOO CA] enum_certificates failed store=%s", store, exc_info=True)
    return out


def _der_to_pem(der: bytes) -> bytes:
    b64 = base64.encodebytes(der).decode("ascii")
    return b"-----BEGIN CERTIFICATE-----\n" + b64.encode("ascii") + b"-----END CERTIFICATE-----\n"


def build_bundle(path: Optional[Path] = None, *, force: bool = False) -> Optional[Path]:
    """certifi + Windows ストア のバンドルを作って返す。作れなければ None。"""
    try:
        import certifi
    except Exception:
        LOG.warning("[YAHOO CA] certifi が無いためバンドルを作成できない")
        return None

    target = Path(path) if path is not None else _default_bundle_path()

    certs = _windows_store_certs()
    if not certs:
        LOG.warning("[YAHOO CA] Windows 証明書ストアから証明書を取得できなかった")
        return None

    try:
        base = Path(certifi.where()).read_bytes()
    except Exception:
        LOG.warning("[YAHOO CA] certifi バンドルを読めなかった", exc_info=True)
        return None

    payload = b"".join([base] + [_der_to_pem(d) for d in certs])

    try:
        if (not force) and target.exists() and target.stat().st_size == len(payload):
            # 中身が同じサイズならそのまま使う (毎回書き直さない)
            return target
        target.parent.mkdir(parents=True, exist_ok=True)
        tmp = target.with_suffix(target.suffix + ".tmp")
        tmp.write_bytes(payload)
        os.replace(str(tmp), str(target))
        LOG.info("[YAHOO CA] バンドル作成 path=%s certs=%s size=%s", target, len(certs), len(payload))
        return target
    except Exception:
        LOG.warning("[YAHOO CA] バンドル書き込みに失敗 path=%s", target, exc_info=True)
        return None


def install(*, force: bool = False) -> bool:
    """バンドルを作り、CA関連の環境変数へ設定する。

    既に環境変数が設定されている場合は尊重して何もしない。
    戻り値: 設定できたら True。
    """
    global _INSTALLED
    if _INSTALLED and not force:
        return True

    if not force:
        already = [v for v in _ENV_VARS if os.environ.get(v, "").strip()]
        if already:
            LOG.info("[YAHOO CA] 既に設定済みのため何もしない: %s", already)
            _INSTALLED = True
            return True

    bundle = build_bundle(force=force)
    if bundle is None or not bundle.exists():
        LOG.warning("[YAHOO CA] バンドルを用意できなかった。Yahoo 取得が失敗する可能性がある")
        return False

    for v in _ENV_VARS:
        os.environ[v] = str(bundle)

    LOG.warning("[YAHOO CA] installed version=%s bundle=%s", VERSION, bundle)
    _INSTALLED = True
    return True


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    ok = install(force=True)
    print("installed:", ok)
    for v in _ENV_VARS:
        print(f"  {v}={os.environ.get(v)}")
